package com.example.starter.reading;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * 浓度检测读数仓储：封存后迟到数据以 late=TRUE 落库，不参与日结统计。
 */
@Repository
public class OdorantReadingRepository {

    private final JdbcTemplate jdbc;

    public OdorantReadingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public void insert(Long stationId, String requestId, java.time.LocalDateTime detectedAt,
                       BigDecimal gasFlowM3, BigDecimal concentrationMgM3,
                       boolean qualified, boolean late) {
        jdbc.update("""
                        INSERT INTO odorant_reading
                            (station_id, request_id, detected_at, gas_flow_m3, concentration_mg_m3,
                             qualified, late)
                        VALUES (?, ?, ?, ?, ?, ?, ?)
                        """,
                stationId, requestId, detectedAt, gasFlowM3, concentrationMgM3, qualified, late);
    }

    /**
     * 统计业务日期内非迟到读数的流量合计 m³。
     */
    public BigDecimal sumFlowByDate(Long stationId, LocalDate bizDate) {
        BigDecimal sum = jdbc.queryForObject("""
                        SELECT COALESCE(SUM(gas_flow_m3), 0)
                        FROM odorant_reading
                        WHERE station_id = ? AND late = FALSE
                          AND detected_at >= ? AND detected_at < ?
                        """,
                BigDecimal.class, stationId, bizDate.atStartOfDay(), bizDate.plusDays(1).atStartOfDay());
        return sum == null ? BigDecimal.ZERO : sum;
    }
}

package com.example.starter.reading;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

import java.time.LocalDateTime;

/**
 * 迟到事件仓储：日结封存后到达的检测只记录迟到事件。
 */
@Repository
public class LateEventRepository {

    private final JdbcTemplate jdbc;
    private final ObjectMapper objectMapper;

    public LateEventRepository(JdbcTemplate jdbc, ObjectMapper objectMapper) {
        this.jdbc = jdbc;
        this.objectMapper = objectMapper;
    }

    public void insert(Long stationId, String sourceType, String requestId,
                       LocalDateTime detectedAt, Object payload) {
        String json;
        try {
            json = objectMapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to serialize late event", e);
        }
        jdbc.update("""
                        INSERT INTO late_event (station_id, source_type, request_id, detected_at, payload_json)
                        VALUES (?, ?, ?, ?, ?)
                        """,
                stationId, sourceType, requestId, detectedAt, json);
    }

    public long countByRequest(String requestId) {
        Long count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM late_event WHERE request_id = ?", Long.class, requestId);
        return count == null ? 0 : count;
    }
}

