        return count == null ? 0 : count;
    }

    public long countCompleted(Long stationId) {
        Long count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM linkage_task WHERE station_id = ? AND status = 'COMPLETED'",
                Long.class, stationId);
        return count == null ? 0 : count;
    }
}

