package com.example.starter.pressure;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * 门站执行中联动任务互斥锁：station_id 主键冲突裁决并发下达，仅一个事务受理成功。
 */
@Repository
public class StationTaskLockRepository {

    private final JdbcTemplate jdbc;

    public StationTaskLockRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 尝试占用门站联动锁。
     *
     * @return true 获得锁；false 已有执行中任务（未受理）
     */
    public boolean tryAcquire(Long stationId, Long taskId) {
        try {
            jdbc.update("INSERT INTO station_task_lock (station_id, task_id) VALUES (?, ?)",
                    stationId, taskId);
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    public void release(Long stationId) {
        jdbc.update("DELETE FROM station_task_lock WHERE station_id = ?", stationId);
    }

    public boolean isLocked(Long stationId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM station_task_lock WHERE station_id = ?",
                Integer.class, stationId);
        return count != null && count > 0;
    }
}

