        // 日结核对的累计流量仍为封存时的 1000m3
        DailyCloseRow row = dailyCloseRepository.find(1L, BIZ_DATE).orElseThrow();
        assertEquals(0, new BigDecimal("1000.000").compareTo(row.totalFlowM3()));
    }
}

