            PressureDetectResponse resp = f.get(15, TimeUnit.SECONDS);
            if (resp.idempotentReplay()) {
                replayCount++;
            } else {
                firstCount++;
                firstTaskId = resp.taskId();
            }
            assertEquals(firstTaskId == null ? resp.taskId() : firstTaskId, resp.taskId());
        }
        pool.shutdown();

