        assertThrows(IdempotentConflictException.class, () -> pressureService.detect(tampered));
        assertEquals(1, count("SELECT COUNT(*) FROM linkage_task WHERE request_id = 'PR-CF'"),
                "同键异参不得新增任务");
    }
}

