import java.time.LocalDateTime;
import java.util.Optional;

/**
 * 锁阀／复开工单仓储：LOCK 与 REOPEN 均须两名不同操作人，单人/同人工单停留 PENDING 不生效。
 */
@Repository
public class LockOrderRepository {

    private final JdbcTemplate jdbc;

    public LockOrderRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Long insert(Long stationId, String action, String status,
                       String firstOperator, String secondOperator, String triggerRequestId) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(connection -> {
            PreparedStatement ps = connection.prepareStatement("""
                            INSERT INTO lock_order
                                (station_id, action, status, first_operator, second_operator,
                                 trigger_request_id, created_at)
                            VALUES (?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
                            """,
                    new String[]{"id"});
            ps.setLong(1, stationId);
            ps.setString(2, action);
            ps.setString(3, status);
            ps.setString(4, firstOperator);
            ps.setString(5, secondOperator);
            ps.setString(6, triggerRequestId);
            return ps;
        }, keyHolder);
        return keyHolder.getKey() == null ? null : keyHolder.getKey().longValue();
    }

    /**
     * 查找门站最近一张由连续越限触发、尚未确认的 LOCK 工单。
     */
    public Optional<Long> findPendingTriggeredLock(Long stationId) {
        return jdbc.query("""
                        SELECT id FROM lock_order
                        WHERE station_id = ? AND action = 'LOCK' AND status = 'PENDING'
                          AND trigger_request_id IS NOT NULL
                        ORDER BY id DESC LIMIT 1
                        """,
                        rs -> rs.next() ? Optional.of(rs.getLong(1)) : Optional.empty(),
                        stationId);
    }

    public long countConfirmed(Long stationId, String action) {
        Long count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM lock_order WHERE station_id = ? AND action = ? AND status = 'CONFIRMED'",
                Long.class, stationId, action);
        return count == null ? 0 : count;
    }
}

